// Uploads the built artifact to the release bucket.
const fs = require("fs");

const BUCKET = process.env.RELEASE_BUCKET || ""; // release bucket name, from the environment
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  // PUT the built artifact to the release bucket under its versioned name.
  fs.writeFileSync(`bucket://${BUCKET}/${name}`, body);
  console.log(`uploaded ${name} (${body.length} bytes)`);
}

main();

// Uploads the built artifact to the release bucket.
const fs = require("fs");
const http = require("http");
const https = require("https");
const { URL } = require("url");

// The release bucket is an S3-compatible endpoint, provided via the
// environment (RELEASE_BUCKET, e.g. https://bucket.example.com).
const BUCKET = process.env.RELEASE_BUCKET || "";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

// PUTs the body to the bucket under the given object name.
function putObject(bucket, name, body) {
  const url = new URL(encodeURI(name), bucket.endsWith("/") ? bucket : bucket + "/");
  const client = url.protocol === "http:" ? http : https;
  const req = client.request(
    url,
    {
      method: "PUT",
      headers: {
        "Content-Type": "application/javascript",
        "Content-Length": body.length,
        ...(process.env.RELEASE_BUCKET_TOKEN
          ? { Authorization: `Bearer ${process.env.RELEASE_BUCKET_TOKEN}` }
          : {}),
      },
    },
    (res) => {
      res.resume(); // drain the response
      res.on("end", () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`uploaded ${name} (${body.length} bytes) -> ${url}`);
          process.exitCode = 0;
        } else {
          console.error(`upload failed: ${name} -> HTTP ${res.statusCode}`);
          process.exitCode = 1;
        }
      });
    }
  );
  req.on("error", (err) => {
    console.error(`upload failed: ${name}: ${err.message}`);
    process.exitCode = 1;
  });
  req.end(body);
}

function main() {
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  const body = fs.readFileSync("dist/app.js");
  putObject(BUCKET, objectName(VERSION), body);
}

main();
